    fun getAllMeals(): Flow<List<MealEntity>>

    @Query("SELECT * FROM mealEntity WHERE boolIsFavourite = 1")
    fun getFavouriteMeals(): Flow<List<MealEntity>>

    @Query("SELECT * FROM mealEntity WHERE strMeal  LIKE '%' || :mealName || '%'")
